from lib import *
chapter(7,'science','heat-transfer-in-nature','Heat Transfer in Nature',
 ('The hot spoon','A steel spoon left in hot tea soon becomes hot at the other end. A fire warms us even from a distance. Heat travels in three ways.'),
 [('Conduction',['In conduction, heat travels through a solid from the hot part to the cooler part without the material moving.','Metals are good conductors. Wood, plastic and air are poor conductors, called insulators.']),
  ('Convection',['In convection, heat is carried by the movement of a liquid or gas. Hot water rises and cooler water sinks, which sets up a circulation.','This is why a room heater warms a room: warm air rises.']),
  ('Radiation',['Radiation is heat travelling as waves, with no material needed. The warmth of the Sun reaches Earth through empty space.','Dark objects absorb more radiation than light ones, so we wear light clothes in summer.']),
  ('Breezes and clothing',['During the day land heats faster than the sea, so warm air rises over land and cool air from the sea blows in: a sea breeze. At night the reverse happens: a land breeze.','Woollen clothes trap air, which is a poor conductor, and keep us warm in winter.'])],
 [('Why do we use a wooden handle on a frying pan?',[('Metal conducts heat to the hand.','Conduction.'),('Wood is a poor conductor so the handle stays cool.','Insulator.')])],
 ('Explain how the Sun\'s heat reaches us.',['It travels by radiation through space.'],['Thinking convection happens in solids.']),
 ['Conduction in solids, convection in fluids, radiation by waves.','Dark things absorb more heat.','Sea and land breezes come from uneven heating.'],
 [mcq('1',1,'Heat travels in a solid by','conduction',[('convection','This needs a fluid.'),('radiation','This needs no material.')],'Particle to particle.'),
  mcq('2',1,'Heat from the Sun reaches us by','radiation',[('conduction','Space has no solid between.'),('convection','Space has no fluid.')],'Through empty space.'),
  tf('3',1,'Metals are good conductors of heat.',True,'Heat passes quickly.'),
  mcq('4',1,'Which is a poor conductor?','Wood',[('Copper','Copper conducts well.'),('Iron','Iron conducts well.')],'Insulator.'),
  mcq('5',2,'A sea breeze blows','from sea to land in the day',[('from land to sea in the day','That is a land breeze at night.'),('only at night','It occurs during the day.')],'Warm air rises over land.'),
  mcq('6',2,'Light clothes in summer because they','reflect more heat',[('absorb more heat','Dark clothes do.'),('conduct heat','Not the reason.')],'Light colours reflect.'),
  tf('7',2,'Convection happens in liquids and gases.',True,'The fluid itself moves.'),
  mcq('8',3,'Woollen clothes keep us warm by','trapping air',[('making heat','Wool does not make heat.'),('conducting heat','It slows heat loss.')],'Trapped air is an insulator.')],
 keep=['conduction','convection','radiation'])
chapter(7,'science','measurement-of-time-and-motion','Measurement of Time and Motion',
 ('The race','Ravi runs 100 m in 20 seconds and Meena in 18 seconds. Who is faster? To compare, we measure time and work out speed.'),
 [('Time',['Long ago people measured time with the Sun, sundials and water clocks. Today we use clocks and watches.','The SI unit of time is the second. 60 seconds make 1 minute and 60 minutes make 1 hour.']),
  ('The simple pendulum',['A pendulum is a small mass hung by a thread that swings back and forth. One complete to-and-fro swing is an oscillation.','The time taken for one oscillation is its time period. For a given pendulum the time period is almost the same each time, so pendulums were used in clocks.']),
  ('Speed',['Speed tells how fast an object moves. Speed equals distance divided by time.','If a car covers 120 km in 2 hours its speed is 60 km per hour.','Speed is measured in metres per second or kilometres per hour.']),
  ('Distance-time graph',['A distance-time graph shows how far an object has gone as time passes. A straight slanted line shows steady speed. A flat line shows the object is at rest.'])],
 [('A cyclist covers 36 km in 3 hours. Find the speed.',[('Speed is distance divided by time.','Formula.'),('36 divided by 3 is 12 km per hour.','Answer.')])],
 ('Explain how you would compare the speed of two runners.',['Same distance, compare the times.','The shorter time means higher speed.'],['Using the longer time as faster.']),
 ['Time is measured in seconds, minutes, hours.','A pendulum has a time period.','Speed = distance / time.','A flat line on a distance-time graph means rest.'],
 [num('1',1,'A car covers 120 km in 2 hours. Speed in km/h',60,'120 divided by 2.',[(240,'You multiplied.')],'km/h'),
  mcq('2',1,'Speed =','distance / time',[('time / distance','This is the inverse.'),('distance x time','This is not speed.')],'How far per unit time.'),
  num('3',1,'How many seconds in 1 minute?',60,'Standard.',[(100,'It is 60, not 100.')],'s'),
  tf('4',1,'One to-and-fro swing of a pendulum is an oscillation.',True,'That is the definition.'),
  num('5',2,'A cyclist covers 36 km in 3 hours. Speed in km/h',12,'36 divided by 3.',[(108,'Divide, do not multiply.')],'km/h'),
  mcq('6',2,'The time of one oscillation is','time period',[('speed','Speed is distance per time.'),('frequency','Frequency is oscillations per second.')],'The period.'),
  mcq('7',2,'A flat line on a distance-time graph means','the object is at rest',[('fast motion','A steep line shows fast motion.'),('falling','Not related.')],'Distance does not change.'),
  num('8',3,'A bus runs at 40 km/h for 3 hours. Distance in km',120,'Speed times time.',[(13,'Do not divide.')],'km')],
 keep=['speed','time period','oscillation'])
chapter(7,'science','life-processes-in-animals','Life Processes in Animals',
 ('Lunch inside you','You eat a roti at lunch. By evening it is gone, but it has become energy and part of your body. How? Animals use food through digestion, breathing, circulation and excretion.'),
 [('Nutrition and digestion',['Animals cannot make their own food. They get nutrients by eating plants or other animals.','Digestion is breaking food into small simple substances the body can absorb. In humans it starts in the mouth, where teeth chew and saliva begins digesting starch.','Food passes through the food pipe to the stomach, where acids and juices work, then to the small intestine, where most digestion and absorption happen. The large intestine takes in water and the rest leaves as waste.']),
  ('Respiration',['Respiration is releasing energy from food using oxygen. We breathe in air with oxygen and breathe out carbon dioxide.','The lungs exchange gases. Fish use gills and insects use tiny tubes.']),
  ('Circulation',['The heart pumps blood through blood vessels to every part of the body. Blood carries food and oxygen to cells and takes away waste.','Red blood cells carry oxygen. Plasma carries food. White blood cells fight germs.']),
  ('Excretion',['Excretion is removing waste from the body. The kidneys filter blood and make urine. Lungs remove carbon dioxide and the skin removes sweat.'])],
 [('Where does most digestion and absorption take place?',[('Food leaves the stomach.','Next organ.'),('It enters the small intestine where most digestion and absorption occur.','Small intestine.')])],
 ('Explain how food reaches every cell of the body.',['Digested food enters blood.','The heart pumps blood everywhere.'],['Thinking respiration is just breathing.']),
 ['Digestion breaks down food.','Respiration releases energy using oxygen.','Blood carries oxygen and food.','Excretion removes wastes.'],
 [mcq('1',1,'Digestion starts in the','mouth',[('stomach','Starch digestion begins in the mouth.'),('large intestine','Absorption of water occurs there.')],'Saliva acts on starch.'),
  mcq('2',1,'Most food is absorbed in the','small intestine',[('stomach','It mainly churns food.'),('mouth','Food is chewed there.')],'It is long with a large surface.'),
  tf('3',1,'Kidneys filter blood.',True,'They make urine.'),
  mcq('4',1,'Which pumps blood?','Heart',[('Lungs','They exchange gases.'),('Kidney','It filters blood.')],'A muscular pump.'),
  mcq('5',2,'Respiration releases','energy',[('only heat','Energy is released.'),('food','Food is the fuel.')],'From food using oxygen.'),
  mcq('6',2,'White blood cells','fight germs',[('carry oxygen','Red cells do.'),('make bones','Not their job.')],'Part of immunity.'),
  tf('7',2,'Fish breathe using gills.',True,'Gills take oxygen from water.'),
  mcq('8',3,'We breathe out','carbon dioxide',[('only oxygen','We use oxygen.'),('only nitrogen','Nitrogen mostly passes through.')],'It is a waste gas.')],
 keep=['digestion','respiration','circulation','excretion'])
